<?php
declare(strict_types=1);
require_once __DIR__.'/../../app/bootstrap.php';require_once __DIR__.'/../../app/templates.php';require_once __DIR__.'/../../app/mysql.php';require_once __DIR__.'/../../app/lab-api.php';
secureHeaders();header('Cache-Control: no-store');$_SERVER['HTTP_X_WORKSPACE_PORTAL']='frontend';
try{
    $base=mcpOAuthBase();if(config()['environment']!=='development'&&(!isset($_SERVER['HTTPS'])||$_SERVER['HTTPS']==='off'))fail(403,'HTTPS erforderlich.');$route=parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH);$method=$_SERVER['REQUEST_METHOD'];
    if(str_starts_with($route,'/.well-known/')){if($method!=='GET')fail(405,'GET erforderlich.');jsonOut(mcpOAuthMetadata(str_contains($route,'oauth-protected-resource')));}
    if($route==='/oauth/authorize/'||$route==='/oauth/authorize'){
        sessionStart();$u=currentUser();$escape=fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
        if($method==='GET'){
            $req=mcpOAuthRequest($_GET);
            if(!$u){$fields='';foreach($_GET as $k=>$v){if(!is_string($v))fail(422,'Ungültige Autorisierung.');$fields.='<input type="hidden" name="'.$escape($k).'" value="'.$escape($v).'">';}mcpOAuthConsentPage('Mit Academy verbinden','<p>Zuerst im eigenen Academy-Konto anmelden. Danach hier fortfahren.</p><p><a class="es-btn es-btn--primary" href="/#agent-lab" target="_blank" rel="noopener">Academy-Anmeldung öffnen</a></p><form method="get" action="/oauth/authorize/">'.$fields.'<button class="es-btn es-btn--secondary">Nach Anmeldung fortfahren</button></form>');}
            $p=mcpOAuthUserProfile($u);$nonce=id();$_SESSION['mcp_consent']=array_filter($_SESSION['mcp_consent']??[],fn($v)=>$v['expires']>time());if(count($_SESSION['mcp_consent'])>=5)array_shift($_SESSION['mcp_consent']);$_SESSION['mcp_consent'][$nonce]=['request'=>$req,'user'=>$u['id'],'version'=>(int)$p['version'],'auth_version'=>(int)$u['auth_version'],'expires'=>time()+600];$tables='';foreach(json_decode($p['selection'],true) as $table=>$cols)$tables.='<li><strong>'.$escape($table).'</strong><br>'.$escape(implode(', ',$cols)).'</li>';
            $clientHost=parse_url($req['redirect'],PHP_URL_HOST);mcpOAuthConsentPage('Datenzugriff freigeben','<p><strong>'.$escape($clientHost).'</strong> möchte auf die freigegebenen Daten von <strong>'.$escape($u['name']).'</strong> zugreifen.</p><p>Nur lesend · maximal '.(int)$p['max_rows'].' Zeilen je Aufruf · keine SQL-Befehle</p><ul>'.$tables.'</ul><p>Im Agent Lab kann diese Verbindung jederzeit abgeschaltet werden. Eine Änderung der Tabellenfreigabe widerruft die Verbindung.</p><form method="post" action="/oauth/authorize/"><input type="hidden" name="csrf" value="'.$escape($_SESSION['csrf']).'"><input type="hidden" name="nonce" value="'.$nonce.'"><button class="es-btn es-btn--primary" name="decision" value="allow">Verbinden & freigeben</button><button class="es-btn es-btn--secondary" name="decision" value="deny">Abbrechen</button></form>');
        }
        if($method!=='POST')fail(405,'Methode nicht erlaubt.');if(!$u||!is_string($_POST['csrf']??null)||!hash_equals($_SESSION['csrf'],$_POST['csrf']))fail(403,'Die Sicherheitsprüfung ist fehlgeschlagen. Bitte erneut verbinden.');$nonce=$_POST['nonce']??'';if(!is_string($nonce))fail(422,'Ungültige Anfrage.');$pending=$_SESSION['mcp_consent'][$nonce]??null;unset($_SESSION['mcp_consent'][$nonce]);if(!$pending||$pending['expires']<=time()||$pending['user']!==$u['id']||$pending['auth_version']!==(int)$u['auth_version'])fail(403,'Diese Freigabe ist abgelaufen. Bitte erneut verbinden.');$req=$pending['request'];$params=['state'=>$req['state'],'iss'=>$base];if(($_POST['decision']??'')==='allow')$params['code']=mcpOAuthCode($u,$req,$pending['version']);else $params['error']='access_denied';header('Location: '.$req['redirect'].'?'.http_build_query($params),true,303);exit;
    }
    if($method!=='POST')fail(405,'POST erforderlich.');if((int)($_SERVER['CONTENT_LENGTH']??0)>16000)fail(413,'Anfrage zu groß.');rateLimit('mcp.oauth.'.$route,str_contains($route,'register')?20:180,str_contains($route,'register')?3600:60);
