}catch(ApiError $e){$route=$route??'';if(str_contains($route,'authorize')){http_response_code($e->status);mcpOAuthConsentPage('Verbindung nicht möglich','<p>'.htmlspecialchars($e->getMessage(),ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8').'</p><p><a href="/#agent-lab">Zum Agent Lab</a></p>');}jsonOut(['error'=>in_array($e->getMessage(),['invalid_grant','invalid_scope','invalid_target','invalid_client'],true)?$e->getMessage():'invalid_request','error_description'=>$e->getMessage()],$e->status);}catch(Throwable){jsonOut(['error'=>'server_error'],500);}
